from z3 import *

def main():
    n = 2

    categories = {
        "name": ["Eric", "Arnold"],
        "music": ["rock", "pop"],
        "style": ["colonial", "victorian"],
        "lunch": ["grilled cheese", "pizza"],
        "sport": ["basketball", "soccer"],
        "child": ["Bella", "Fred"],
    }

    solver = Solver()
    house_of = {}

    for cat, values in categories.items():
        cat_vars = []
        for value in values:
            var_name = f"{cat}_{value}".replace(" ", "_")
            var = Int(var_name)
            house_of[(cat, value)] = var
            solver.add(var >= 1, var <= n)
            cat_vars.append(var)
        solver.add(Distinct(cat_vars))

    solver.add(house_of[("style", "colonial")] == house_of[("lunch", "pizza")])
    solver.add(house_of[("name", "Arnold")] == house_of[("style", "colonial")])
    solver.add(house_of[("music", "pop")] == house_of[("style", "colonial")])
    solver.add(house_of[("lunch", "pizza")] != 2)
    solver.add(house_of[("name", "Eric")] == house_of[("sport", "soccer")])
    solver.add(house_of[("lunch", "grilled cheese")] == house_of[("child", "Bella")])

    if solver.check() != sat:
        return

    model = solver.model()

    def get_attribute(cat, house):
        for value in categories[cat]:
            if model.evaluate(house_of[(cat, value)]).as_long() == house:
                return value
        return "unknown"

    order = ["name", "music", "style", "lunch", "sport", "child"]

    for house in range(1, n + 1):
        attrs = [get_attribute(cat, house) for cat in order]
        print(f"House {house}: " + ", ".join(attrs))

if __name__ == "__main__":
    main()

