    nationalities = ["swede", "dane", "brit"]

    s = Solver()

    name_house = {name: Int(f"name_{i}") for i, name in enumerate(names)}
    car_house = {car: Int(f"car_{i}") for i, car in enumerate(cars)}
    nationality_house = {nat: Int(f"nationality_{i}") for i, nat in enumerate(nationalities)}

    for category in [name_house, car_house, nationality_house]:
        s.add(Distinct(*category.values()))

    for var in list(name_house.values()) + list(car_house.values()) + list(nationality_house.values()):
        s.add(var >= 1, var <= 3)

    # 1. The person who owns a Ford F-150 is somewhere to the right of the Swedish person.
