    # 4. Eric is the person who owns a Ford F-150.
    s.add(name_house["Eric"] == car_house["ford f150"])

    # 5. The British person is not in the third house.
    s.add(nationality_house["brit"] != 3)

    if s.check() != sat:
        print("No solution")
        return

    model = s.model()

    def house_of(var):
        return model.eval(var, model_completion=True).as_long()

    name_by_house = {house_of(name_house[name]): name for name in names}
    car_by_house = {house_of(car_house[car]): car for car in cars}
