from z3 import *

def main():
    names = ["Alice", "Peter", "Arnold", "Eric"]
    lunches = ["grilled cheese", "spaghetti", "pizza", "stew"]

    name_id = {n: i for i, n in enumerate(names)}
    lunch_id = {l: i for i, l in enumerate(lunches)}

    s = Solver()

    Name = [Int(f"Name_{i + 1}") for i in range(4)]
    Lunch = [Int(f"Lunch_{i + 1}") for i in range(4)]

    for v in Name:
        s.add(0 <= v, v < 4)
    for v in Lunch:
        s.add(0 <= v, v < 4)

    s.add(Distinct(Name))
    s.add(Distinct(Lunch))

    for i in range(4):
        s.add(Implies(Name[i] == name_id["Arnold"], Lunch[i] == lunch_id["grilled cheese"]))
        s.add(Implies(Lunch[i] == lunch_id["grilled cheese"], Name[i] == name_id["Arnold"]))

    s.add(Lunch[2] == lunch_id["grilled cheese"])
    s.add(Lunch[1] != lunch_id["stew"])
    s.add(Lunch[3] != lunch_id["stew"])

    for i in range(4):
        s.add(Implies(Name[i] == name_id["Eric"], Lunch[i] == lunch_id["spaghetti"]))
        s.add(Implies(Lunch[i] == lunch_id["spaghetti"], Name[i] == name_id["Eric"]))

    for i in range(4):
        for j in range(4):
            if i <= j:
                s.add(Not(And(Name[i] == name_id["Peter"], Lunch[j] == lunch_id["spaghetti"])))

    if s.check() == sat:
        m = s.model()
        for h in range(4):
            person = names[m.eval(Name[h]).as_long()]
            lunch = lunches[m.eval(Lunch[h]).as_long()]
            print(f"House {h + 1}: {person}, {lunch}")

if __name__ == "__main__":
    main()

