    name_attrs = ["Arnold", "Eric"]
    car_attrs = ["tesla model 3", "ford f150"]
    child_attrs = ["Fred", "Bella"]

    name_pos = {attr: Int(attr.replace(" ", "_")) for attr in name_attrs}
    car_pos = {attr: Int(attr.replace(" ", "_")) for attr in car_attrs}
    child_pos = {attr: Int(attr.replace(" ", "_")) for attr in child_attrs}

    all_pos = list(name_pos.values()) + list(car_pos.values()) + list(child_pos.values())

    for pos in all_pos:
        solver.add(pos >= 1, pos <= 2)

    solver.add(Distinct(list(name_pos.values())))
    solver.add(Distinct(list(car_pos.values())))
    solver.add(Distinct(list(child_pos.values())))

    solver.add(name_pos["Arnold"] < name_pos["Eric"])
    solver.add(child_pos["Fred"] > car_pos["tesla model 3"])

    if solver.check() != sat:
        print("No solution")
        return

    model = solver.model()

    def attr_at(category_pos, house):
        for attr, var in category_pos.items():
            if model.eval(var, model_completion=True).as_long() == house:
                return attr
        return "Unknown"

    for house in (1, 2):
        name = attr_at(name_pos, house)
        car = attr_at(car_pos, house)
        child = attr_at(child_pos, house)
        print(f"House {house}: {name}, {car}, {child}")

